locationRouter.get("/:path{.+}", optionalAuthMiddleware, async (c2) => {
  const auth = c2.get("user");
  const db = c2.get("db");
  const env2 = c2.get("env");
  const imageUploadService = new ImageUploadService(db, env2);
  const locationService = new LocationService(db, imageUploadService);
  const fullPath = c2.req.param("path");
  if (fullPath.endsWith("/explore")) {
    const locationPath = fullPath.replace(/\/explore$/, "");
    const typesParam = c2.req.query("types");
    const types2 = typesParam ? typesParam.split(",").filter(Boolean) : void 0;
    const page = Number(c2.req.query("page") ?? "1");
    const swLat = c2.req.query("swLat");
    const swLng = c2.req.query("swLng");
    const neLat = c2.req.query("neLat");
    const neLng = c2.req.query("neLng");
    const bbox = swLat && swLng && neLat && neLng ? {
      swLat: Number(swLat),
      swLng: Number(swLng),
      neLat: Number(neLat),
      neLng: Number(neLng)
    } : void 0;
    const result2 = await locationService.getExplorePlaces(
      locationPath,
      { types: types2, page, bbox },
      auth?.id
    );
    return c2.json(result2, 200);
  }
  if (fullPath.endsWith("/children")) {
    const locationPath = fullPath.replace(/\/children$/, "");
    const depth = Math.min(Number(c2.req.query("depth") ?? "1"), 3);
    const result2 = await locationService.getChildLocations(locationPath, depth);
    return c2.json(result2, 200);
  }
  if (fullPath.endsWith("/nearby")) {
    const locationPath = fullPath.replace(/\/nearby$/, "");
    const result2 = await locationService.getNearbyLocations(locationPath);
    return c2.json(result2, 200);
  }
  if (fullPath.endsWith("/photos")) {
    const locationPath = fullPath.replace(/\/photos$/, "");
    const page = Number(c2.req.query("page") ?? "1");
    const limit = Number(c2.req.query("limit") ?? "12");
    const result2 = await locationService.getLocationPhotos(locationPath, page, limit);
    return c2.json(result2, 200);
  }
  if (fullPath.endsWith("/places")) {
    const locationPath = fullPath.replace(/\/places$/, "");
    const placeSort = c2.req.query("placeSort");
    const result2 = await locationService.getLocationPlaces(
      locationPath,
      { placeSort },
      auth?.id
    );
    return c2.json(result2, 200);
  }
  const result = await locationService.getLocation(fullPath, auth?.id);
  return c2.json(result, 200);
});
locationRouter.get("/sitemap", async (c2) => {
  const db = c2.get("db");
  const locations = await db.select({ path: Location.path, updatedAt: Location.updatedAt }).from(Location).orderBy(asc(Location.path));
  return c2.json(locations, 200);
});

