placeRouter.post(
  "/suggest-edit",
  authMiddleware,
  zValidator("json", suggestEditSchema),
  async (c2) => {
    const auth = c2.get("user");
    const db = c2.get("db");
    const env2 = c2.get("env");
    const { placeId, field, suggestedValue, notes } = c2.req.valid("json");
    const pendingResult = await db.select({ pendingCount: count() }).from(PlaceSuggestedEdit).where(
      and(
        eq(PlaceSuggestedEdit.placeId, placeId),
        eq(PlaceSuggestedEdit.userId, auth.id),
        eq(PlaceSuggestedEdit.status, "pending")
      )
    );
    if ((pendingResult[0]?.pendingCount ?? 0) >= 5) {
      throw new BadRequestError("You have too many pending suggestions for this place");
    }
    const [place] = await db.select().from(Place).where(eq(Place.id, placeId)).limit(1);
    if (!place) throw new BadRequestError("Place not found");
    const currentValue = place[field] ?? null;
    const [edit] = await db.insert(PlaceSuggestedEdit).values({
      placeId,
      userId: auth.id,
      field,
      currentValue,
      suggestedValue,
      notes
    }).returning();
    sendDiscordSuggestedEditNotification(env2, {
      placeName: place.name,
      placeSlug: place.slug,
      locationPath: "",
      // location path not on Place directly, just omit for now
      userName: auth.name ?? auth.email,
      field,
      suggestedValue,
      notes
    }).catch(() => {
    });
    return c2.json({ id: edit.id }, 201);
  }
);
placeRouter.get("/:placeId/fetch-images", async (c2) => {
  const db = c2.get("db");
  const env2 = c2.get("env");
  const placeId = c2.req.param("placeId");
  const imageUploadService = new ImageUploadService(db, env2);
  const collectionService = new CollectionService(db, imageUploadService);
  const placeService = new PlaceService(db, imageUploadService, collectionService, env2);
  const [place] = await db.select().from(Place).where(eq(Place.id, placeId)).limit(1);
  if (!place) throw new BadRequestError("Place not found");
  const [location] = await db.select({ countryCode: Location.countryCode, name: Location.name }).from(Location).where(eq(Location.id, place.locationId)).limit(1);
  if (!location) throw new BadRequestError("Location not found");
  await placeService.fetchAndStoreGoogleImages(placeId, place.name, location.countryCode, location.name);
  return c2.json({ success: true }, 200);
});
placeRouter.get("/:path{.*}", optionalAuthMiddleware, async (c2) => {
  const auth = c2.get("user");
  const db = c2.get("db");
  const env2 = c2.get("env");
  const imageUploadService = new ImageUploadService(db, env2);
  const collectionService = new CollectionService(db, imageUploadService);
  const placeService = new PlaceService(
    db,
    imageUploadService,
    collectionService,
    env2
  );
  const path2 = c2.req.param("path");
  const segments = path2.split("/");
  const slug = segments.pop();
  const locationPath = segments.join("/");
  if (!slug) {
    throw new BadRequestError("Slug is required");
  }
  const result = await placeService.getPlace(locationPath, slug, auth?.id);
  if (result.images.length === 0) {
    c2.executionCtx.waitUntil(
      placeService.fetchAndStoreGoogleImages(
        result.id,
        result.name,
        result.location.countryCode
      )
    );
  }
  return c2.json(result, 200);
});

